/* Audited shared-workspace controls: case lifecycle, roster, help and exports. */
let editingSharedCase=null,assigningCase=null;
const canManageCases=()=>workspace&&['administrator','supervisor','intake'].includes(workspace.role);
byId('staff-app').insertAdjacentHTML('beforeend',`<section id="cases-panel" class="panel" hidden><div class="panel-title"><div><h2>Cases &amp; staff</h2><p>Create a case folder, keep labels current, and manage case access.</p></div><button class="primary" id="new-shared-case">＋ Create case</button></div><div class="queue-toolbar"><label>Search cases<input type="search" id="shared-case-search" placeholder="Case label"></label><button id="refresh-cases">Refresh cases</button></div><p id="case-directory-count" class="muted" role="status"></p><div id="case-directory"></div></section>`);
const sharedHelp=opsDialog('staff-help-dialog',`<div class="dialog-heading"><h2>Staff workspace help</h2><button type="button" data-ops-close aria-label="Close help">×</button></div><p>Use Cases &amp; staff to create case folders and assign their care team. Then plan sessions, record attendance, manage the waitlist, and assign follow-up tasks.</p><p>Case and staff access is checked when each action is saved. Refresh a list if another team member changed a record while you were editing it.</p><div class="workspace-links"><a href="index.html?portal=client">Open client intake preview →</a><a href="index.html?portal=admin">Open local care-workspace preview →</a><a href="about-eero.html">Eero services &amp; contact →</a></div><p class="muted">These previews use separate sample data. Staff sign-in must be configured before shared records are available. No email or text is sent by slot offers or task updates.</p>`);
byId('staff-help').onclick=()=>sharedHelp.showModal();
const sharedCaseDialog=opsDialog('shared-case-dialog',`<form id="shared-case-form"><div class="dialog-heading"><h2 id="shared-case-heading">Create case folder</h2><button type="button" data-ops-close aria-label="Close case editor">×</button></div><label>Case label<input id="shared-case-label" maxlength="120" required placeholder="Use a fictional case label"></label><label id="case-status-label">Status<select id="shared-case-status"><option value="active">Active</option><option value="closed">Closed</option></select></label><p class="muted">Closing retains case records. Complete open tasks, resolve active waitlist requests, and cancel or complete future sessions first.</p><p id="shared-case-error" class="error" role="alert" hidden></p><div class="dialog-actions"><button type="button" data-ops-close>Cancel</button><button class="primary">Save case</button></div></form>`);
const sharedRosterDialog=opsDialog('case-roster-dialog',`<form id="case-roster-form"><div class="dialog-heading"><h2>Manage case staff</h2><button type="button" data-ops-close aria-label="Close case staff">×</button></div><p id="case-roster-label"></p><label>Staff member<select id="case-roster-person" required></select></label><p id="case-roster-error" class="error" role="alert" hidden></p><div class="dialog-actions"><button type="button" data-ops-close>Cancel</button><button class="primary">Assign to case</button></div></form><div id="case-roster-current"></div>`);
function paintCases(){if(!workspace)return;const q=byId('shared-case-search').value.trim().toLowerCase();const cases=workspace.cases.filter(c=>c.label.toLowerCase().includes(q));byId('case-directory-count').textContent=`${cases.length} accessible case folders`;byId('case-directory').innerHTML=cases.map(c=>`<article class="ops-card"><div><span class="status">${c.status==='closed'?'Closed':'Active'}</span><h3>${escapeHTML(c.label)}</h3><p>${workspace.case_assignments.filter(a=>a.case_id===c.id).length} assigned staff</p></div><div class="ops-actions">${canManageCases()?`<button data-edit-shared-case="${escapeHTML(c.id)}">Edit case</button>`:''}${['administrator','supervisor'].includes(workspace.role)?`<button data-case-roster="${escapeHTML(c.id)}">Manage staff</button>`:''}${c.status!=='closed'?`<button data-case-session="${escapeHTML(c.id)}">Plan session</button><button data-case-task="${escapeHTML(c.id)}">Create follow-up</button>`:''}</div></article>`).join('')||'<div class="empty">No case folders match. Create a case or ask your supervisor for an assignment.</div>';byId('new-shared-case').hidden=!canManageCases()}
function editSharedCase(id){editingSharedCase=workspace.cases.find(c=>c.id===id)||null;byId('shared-case-form').reset();byId('shared-case-label').value=editingSharedCase?.label||'';byId('shared-case-status').value=editingSharedCase?.status||'active';byId('case-status-label').hidden=!editingSharedCase;byId('shared-case-heading').textContent=editingSharedCase?'Edit case folder':'Create case folder';byId('shared-case-error').hidden=true;sharedCaseDialog.showModal()}
byId('new-shared-case').onclick=()=>editSharedCase();byId('shared-case-form').onsubmit=e=>{e.preventDefault();saveOpsForm(e.target,'shared-case-error',()=>post(editingSharedCase?'/api/cases/update':'/api/cases',editingSharedCase?{id:editingSharedCase.id,version:editingSharedCase.version,label:byId('shared-case-label').value.trim(),status:byId('shared-case-status').value}:{label:byId('shared-case-label').value.trim()}),sharedCaseDialog,refreshWorkspace)};
function openRoster(id){assigningCase=workspace.cases.find(c=>c.id===id);byId('case-roster-label').textContent=assigningCase.label;byId('case-roster-person').innerHTML=workspace.assignable_staff.map(s=>`<option value="${escapeHTML(s.id)}">${escapeHTML(s.name)} · ${escapeHTML(s.role)}</option>`).join('');byId('case-roster-error').hidden=true;byId('case-roster-current').innerHTML='<h3>Current case team</h3>'+workspace.case_assignments.filter(a=>a.case_id===id).map(a=>`<div class="time-off-row"><span>${escapeHTML(a.name)} · ${escapeHTML(a.role)}${a.active?'':' · inactive'}</span><button type="button" data-remove-case-staff="${escapeHTML(a.user_id)}">Remove access</button></div>`).join('');sharedRosterDialog.showModal()}
byId('case-roster-form').onsubmit=e=>{e.preventDefault();saveOpsForm(e.target,'case-roster-error',()=>post('/api/cases/assignment',{id:assigningCase.id,version:assigningCase.version,user_id:byId('case-roster-person').value,action:'Assign'}),sharedRosterDialog,refreshWorkspace)};
byId('case-roster-current').onclick=async e=>{const b=e.target.closest('[data-remove-case-staff]');if(!b||!confirm('Remove this staff member’s access to this case?'))return;b.disabled=true;try{await post('/api/cases/assignment',{id:assigningCase.id,version:assigningCase.version,user_id:b.dataset.removeCaseStaff,action:'Remove'});sharedRosterDialog.close();await refreshWorkspace()}catch(error){byId('case-roster-error').textContent=error.message;byId('case-roster-error').hidden=false;b.disabled=false}};
byId('case-directory').onclick=e=>{const edit=e.target.closest('[data-edit-shared-case]'),roster=e.target.closest('[data-case-roster]'),session=e.target.closest('[data-case-session]'),task=e.target.closest('[data-case-task]');if(edit)editSharedCase(edit.dataset.editSharedCase);if(roster)openRoster(roster.dataset.caseRoster);if(session){openSession();byId('shared-case').value=session.dataset.caseSession;byId('shared-case').dispatchEvent(new Event('change'))}if(task){openTask();byId('work-task-case').value=task.dataset.caseTask;byId('work-task-case').dispatchEvent(new Event('change'))}};
byId('shared-case-search').oninput=paintCases;byId('refresh-cases').onclick=async()=>{try{await refreshWorkspace()}catch(error){message(error.message)}};
byId('schedule-panel').querySelector('.panel-title').insertAdjacentHTML('afterend','<div class="schedule-tools"><button id="clear-schedule-filters">Clear schedule filters</button><button id="export-calendar">Export loaded sessions (.ics)</button><button id="print-schedule">Print schedule</button></div>');
byId('clear-schedule-filters').onclick=()=>{byId('session-search').value='';byId('attendance-filter').value='';const day=parts(new Date().toISOString()).date;byId('from-date').value=day;const last=new Date(day+'T12:00:00Z');last.setUTCDate(last.getUTCDate()+180);byId('to-date').value=last.toISOString().slice(0,10);loadAgenda()};
byId('export-calendar').onclick=()=>{if(!appointments.length){message('Load sessions before exporting the schedule.');return}const q=byId('session-search').value.trim().toLowerCase();const rows=appointments.filter(a=>`${a.title} ${caseLabel(a.case_id)} ${staffLabel(a.clinician_id)}`.toLowerCase().includes(q));const url=URL.createObjectURL(new Blob([EeroCalendarExport.calendar(rows)],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='eero-loaded-schedule.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message(`${rows.length} loaded sessions exported. Load additional pages before exporting a larger schedule.`)};
byId('print-schedule').onclick=()=>window.print();
byId('tasks-panel').querySelector('.queue-toolbar').insertAdjacentHTML('beforeend','<button id="clear-task-filters">Clear task filters</button>');byId('clear-task-filters').onclick=()=>{byId('task-state-filter').value='Open';byId('task-assignee-filter').value='';byId('task-priority-filter').value='';byId('task-search').value='';loadTasks()};
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{byId('cases-panel').hidden=b.dataset.tab!=='cases';if(b.dataset.tab==='cases')paintCases()}));
window.addEventListener('eero:workspace-ready',paintCases);window.addEventListener('eero:session-ended',()=>{byId('case-directory').replaceChildren();for(const d of [sharedCaseDialog,sharedRosterDialog]){d.querySelector('form').reset();if(d.open)d.close()}});
